// Clasifica el evento enviado por el backend y decide si abrir una incidencia.
// Estado persistente del flujo (contadores, IPs conocidas, deduplicación) en staticData.
const ev = $input.first().json.body || {};
const st = $getWorkflowStaticData('global');
st.fallidos = st.fallidos || {};
st.ipsAdmin = st.ipsAdmin || {};
st.abiertas = st.abiertas || {};

const ahora = Date.now();
const VENTANA_MS = 5 * 60 * 1000;   // fuerza bruta: ventana de 5 minutos
const UMBRAL = 10;                  // logins fallidos por IP en la ventana
const DEDUP_MS = 60 * 60 * 1000;    // no repetir la misma incidencia durante 1 hora
const ip = String(ev.ip || 'desconocida');
let inc = null;

if (ev.tipo === 'login_fallido') {
  const arr = (st.fallidos[ip] || []).filter((t) => ahora - t < VENTANA_MS);
  arr.push(ahora);
  st.fallidos[ip] = arr;
  if (arr.length >= UMBRAL) {
    inc = { clave: `fuerza-bruta:${ip}`, categoria: 'Seguridad', severidad: 'major', prioridad: 'high',
      resumen: `Posible fuerza bruta: ${arr.length} logins fallidos en 5 min desde ${ip}`,
      clasificacion: 'Fuerza bruta / credential stuffing' };
  }
} else if (ev.tipo === 'rate_limit') {
  inc = { clave: `rate-limit:${ev.limite}:${ip}`, categoria: 'Seguridad', severidad: 'minor', prioridad: 'normal',
    resumen: `Rate limit (${ev.limite || 'api'}) activado para ${ip}`,
    clasificacion: ev.limite === 'auth' ? 'Fuerza bruta frenada por rate limit' : 'Abuso de API / scraping' };
} else if (ev.tipo === 'login_admin') {
  const uid = String(ev.usuario_id);
  const conocidas = st.ipsAdmin[uid] || [];
  if (!conocidas.includes(ip)) {
    // El primer login de cada admin solo registra la IP de referencia.
    if (conocidas.length > 0) {
      inc = { clave: `admin-ip-nueva:${uid}:${ip}`, categoria: 'Seguridad', severidad: 'major', prioridad: 'urgent',
        resumen: `Login de administrador (${ev.email}) desde IP nueva ${ip}`,
        clasificacion: 'Posible robo de credenciales de admin' };
    }
    st.ipsAdmin[uid] = [...conocidas, ip].slice(-20);
  }
}

// Limpieza de contadores viejos para que el estado no crezca sin límite.
for (const k of Object.keys(st.fallidos)) {
  st.fallidos[k] = st.fallidos[k].filter((t) => ahora - t < VENTANA_MS);
  if (!st.fallidos[k].length) delete st.fallidos[k];
}
for (const k of Object.keys(st.abiertas)) if (ahora - st.abiertas[k] > DEDUP_MS) delete st.abiertas[k];

let motivo = inc ? 'nueva incidencia' : 'solo registro';
if (inc && st.abiertas[inc.clave]) { motivo = 'duplicada (ya informada en la última hora)'; inc = null; }
if (inc) st.abiertas[inc.clave] = ahora;

return [{ json: { evento: ev, crear_incidencia: Boolean(inc), incidencia: inc, motivo } }];
